radar-beta
  title Restaurant Comparison
  axis food["Food Quality"], service["Service"], price["Price"]
  axis ambiance["Ambiance"]

  curve a["Restaurant A"]{4, 3, 2, 4}
  curve b["Restaurant B"]{3, 4, 3, 3}
  curve c["Restaurant C"]{2, 3, 4, 2}
  curve d["Restaurant D"]{2, 2, 4, 3}

  graticule polygon
  max 5

radar-beta
title Referenced axes in different orders
axis A["Accessibility"], B["Baseline"], C["Clarity"], D["Depth"], E["Efficiency"]
curve old["Previous release"]{E: 6, C: 5, A: 7, D: 4, B: 3}
curve now["Current release"]{C 8, A 9, E 8, B 7, D 6}
curve target["Target"]{B: 10, D: 10, A: 10, E: 10, C: 10}
graticule polygon
min 2, max 10, ticks 8

radar-beta
title Eight dimensions with a compact canvas
axis A["Input latency"], B["Document fidelity"], C["Export quality"], D["Memory efficiency"]
axis E["Search quality"], F["Interoperability"], G["Accessibility"], H["Reliability"]
curve a["Version A"]{8,6,7,5,8,7,9,6}
curve b["Version B"]{7,9,8,8,6,9,8,9}
curve c["Goal"]{10,10,10,10,10,10,10,10}
max 10, ticks 5

radar-beta
axis A, B, C, D, E, F
curve a{0,2,4,6,8,12}
curve b{12,8,6,4,2,0}
min 2, max 8, ticks 6, showLegend false
